//首页信息
// 获取队伍列表（通过主题 ID）
export const getTeamList = ({ themeId, pageNo = 1, pageSize = 4, isAsc = true }) => {
  const bodyData = { pageNo, pageSize, isAsc }
  return http('/team/list', {
    params: { themeId },
    body: bodyData
  }, 'POST')
}



